from __future__ import annotations

import csv
import io


def parse_customers(text: str) -> list[dict[str, str]]:
    """Parse customer CSV text without altering field contents."""
    if text.startswith("\ufeff"):
        text = text[1:]

    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader)
        if header != ["id", "name", "email"]:
            raise ValueError("CSV header must be id,name,email")

        customers: list[dict[str, str]] = []
        for row in reader:
            if not row:
                continue
            if len(row) != 3:
                raise ValueError("CSV row must contain id, name, and email")
            customers.append(
                {"id": row[0], "name": row[1], "email": row[2]}
            )
        return customers
    except csv.Error as exc:
        raise ValueError("Invalid CSV data") from exc
    except StopIteration as exc:
        raise ValueError("CSV header is required") from exc
